static void gnss_flush_host_rx(int fd)
{
  char dump[64];
  int n;
  int loops = 0;

  if (fd < 0) {
    return;
  }

  /* 切 VCC 时 USART2 仍 open，丢掉断电期间浮空 RX 攒下的字节。 */
  while (loops++ < 32) {
    n = (int)read(fd, dump, sizeof(dump));
    if (n <= 0) {
      break;
    }
  }
}

