  g_mod_up_ms = gnss_now_ms();

  gnss_flush_host_rx(fd);
  gnss_rt_mark("cfg-flush");
  gnss_enable_zda(fd);
  gnss_rt_mark("cfg-zda");
  gnss_configure_nav(fd);
  gnss_rt_mark("cfg-nav");
  if (hold_eph) {
    g_eph_hold = false;
    g_eph_pending = false;
    syslog(LOG_WARNING, "gnss: skip eph inject (recover without mga)\n");
