           * 被吞掉的间隔数字留下来，免得后面没人知道它有多长。 */
          g_rd_selfblock_logged = true;
          syslog(LOG_INFO,
                 "gnss: reader gap %u ms suppressed (self eph/park window)\n",
                 (unsigned)gap);
        }
      }
    }

    g_rd_last_ok_ms = rd_now;
  }

  rxn = rc;
  rxi = 0;
  if (g_idle_parked) {
    /* 模组 VCC 已关：丢掉浮空 RX，UART 仍按 NSH 方式一直收。 */
    rxi = rxn;
