#  define GNSS_PWR_ON_LEVEL   GPIO_PIN_SET
#  define GNSS_PWR_OFF_LEVEL  GPIO_PIN_RESET
#  define GNSS_PWR_PIN_PULL   PIN_PULLDOWN
#else
#  define GNSS_PWR_ON_LEVEL   GPIO_PIN_RESET
#  define GNSS_PWR_OFF_LEVEL  GPIO_PIN_SET
