{
  int ret;

  sf32lb52_l96_uart_pins();

  /* PA43 GNSS_PWR: idle = off (pull matches polarity). */

  HAL_PIN_Set(PAD_PA43, GPIO_A43, GNSS_PWR_PIN_PULL, 1);

  ret = sf32lb52_l96_power(false);
  if (ret < 0)
    {
      return ret;
    }

  usleep(100 * 1000);

  ret = sf32lb52_l96_power(true);
